-- Camera/ShoulderCam.lua
L["Toggle Shoulder Cam"] = "어깨 카메라 켜기/끄기"
L["Moves the camera over your shoulder, using one of Blizzard's experimental camera settings."] = "블리자드의 실험적 카메라 설정 하나를 써서 카메라를 어깨 너머로 옮깁니다."
L["Why the Shoulder Cam pauses while the gamepad UI is on."] = "게임패드 UI가 켜져 있는 동안 어깨 카메라가 멈추는 이유."
L["Puts the camera over your left shoulder instead of your right."] = "카메라를 오른쪽 대신 왼쪽 어깨 너머에 둡니다."
L["How far from the middle of the screen you sit."] = "캐릭터가 화면 가운데에서 얼마나 떨어져 있을지."
L["Spot zoomed out"] = "축소했을 때 위치"
L["Zoomed out at"] = "축소 기준 거리"
L["How long the camera takes to swap to your other shoulder."] = "카메라가 반대쪽 어깨로 넘어가는 데 걸리는 시간."
L["How long the camera takes to go back over your shoulder after you stop targeting yourself."] = "자신을 대상으로 잡지 않게 된 뒤 카메라가 어깨 너머로 돌아가는 데 걸리는 시간."
L["How long the camera takes to move behind you when the Shoulder Cam pauses, and back."] = "어깨 카메라가 멈출 때 카메라가 뒤로 갔다가 다시 돌아오는 데 걸리는 시간."
L["The camera turns toward the NPC you talk to while their window is open."] = "NPC 창이 열려 있는 동안 카메라가 대화하는 NPC 쪽으로 돕니다."
L["Where the camera turns toward who you talk to."] = "카메라가 대화 상대 쪽으로 도는 곳."
L["Escape clears your target and closes an NPC's window in one press."] = "Esc를 한 번 누르면 대상을 해제하고 NPC 창을 닫습니다."
L["Multi Quest fix"] = "다중 퀘스트 수정"
L["Dev test: at a quest giver with more quests, Accept clears your target first."] = "개발 시험: 퀘스트가 더 있는 퀘스트 NPC에서 수락하면 먼저 대상을 해제합니다."
L["How long the camera takes to glide back over your shoulder after you close the window."] = "창을 닫은 뒤 카메라가 어깨 너머로 부드럽게 돌아가는 데 걸리는 시간."
L["Turns to your target everywhere, in fights too."] = "전투 중에도 어디서나 대상 쪽으로 돕니다."
L["The camera turns slowly toward the enemy you target."] = "카메라가 대상으로 잡은 적 쪽으로 천천히 돕니다."
L["Where the camera turns toward your target."] = "카메라가 대상 쪽으로 도는 곳."
L["How long the turn toward your target takes."] = "대상 쪽으로 도는 데 걸리는 시간."
L["Enemy turn back takes"] = "적에서 돌아오는 시간"
L["How long the camera takes to glide back after you clear your target."] = "대상을 해제한 뒤 카메라가 부드럽게 돌아가는 데 걸리는 시간."
L["Glide back when you clear your target"] = "대상 해제 시 부드럽게 돌아가기"
L["Glides back instead of snapping when you clear your target, briefly using soft enemy targeting."] = "대상을 해제할 때 확 튀지 않고 부드럽게 돌아갑니다. 잠깐 적 자동 대상 지정을 씁니다."
L["The ticked frames slide over to where you are on the screen."] = "체크한 창이 화면에서 캐릭터가 있는 쪽으로 미끄러져 갑니다."
L["Your cast bar and Personal Resource Display slide along as the camera turns to your target."] = "카메라가 대상 쪽으로 돌 때 시전 바와 개인 자원 표시도 함께 미끄러집니다."
L["Slides with you."] = "함께 미끄러집니다."
L["Loss of control"] = "제어 불가"
L["Floating combat text"] = "전투 문자"
L["Raises or lowers all the ticked frames while the camera is over your shoulder."] = "카메라가 어깨 너머에 있는 동안 체크한 창을 모두 올리거나 내립니다."
L["How far the frames slide; adjust it if they land short of you or past you."] = "창이 미끄러지는 거리. 캐릭터에 못 미치거나 지나치면 조절하세요."
L["This frame's own height, added to Height (all)."] = "높이 (전체)에 더해지는 이 창만의 높이."
L["Flight paths and their fly-bys."] = "비행 경로와 플라이바이."

