L["off with %s"] = "%s 때문에 꺼짐"
L["How fast the UI fades and what brings it back while CineMode is on."] = "CineMode 중 UI가 흐려지는 속도와 UI를 다시 불러오는 것."
L["How fast the UI fades, the Calm Timer, and fights coming in."] = "UI가 흐려지는 속도, 진정 타이머, 전투 시작."
L["What takes you out of CineMode: fights, places, groups, moving and windows."] = "CineMode에서 벗어나게 하는 것: 전투, 장소, 파티, 이동, 창."
