L["Exit CineMode while an NPC window, like a quest giver or vendor, is open."] = "퀘스트 NPC나 상인 같은 NPC 창이 열려 있는 동안 CineMode를 끝냅니다."
L["Exit CineMode while a game window, like your bags or the map, is open."] = "가방이나 지도 같은 게임 창이 열려 있는 동안 CineMode를 끝냅니다."
L["Picking up an item or spell brings the UI back until you put it down."] = "아이템이나 주문을 집어 들면 내려놓을 때까지 UI가 돌아옵니다."
L["How long things must stay calm before CineMode comes back."] = "CineMode가 돌아오기 전에 조용히 있어야 하는 시간."
L["Casting at an enemy out of combat brings up your combat frames."] = "전투 밖에서 적에게 시전하면 전투 창이 나타납니다."
L["Being in combat brings the UI back."] = "전투 중이면 UI가 돌아옵니다."
L["In the open world"] = "필드에서"
L["Anywhere outside cities, dungeons and raids."] = "도시, 던전, 공격대 밖 어디서나."
L["Capital cities, including Dalaran."] = "달라란을 포함한 수도."
L["While you're flagged for PvP out in the world."] = "필드에서 PvP가 활성화된 동안."
L["In battlegrounds"] = "전장에서"
L["Battlegrounds and arenas."] = "전장과 투기장."
L["Back after stopping"] = "멈춘 뒤 복귀"
L["CineMode comes back once you've stood still this long."] = "이만큼 가만히 서 있으면 CineMode가 돌아옵니다."
L["Back after moving"] = "움직인 뒤 복귀"
L["CineMode comes back once you've kept moving this long."] = "이만큼 계속 움직이면 CineMode가 돌아옵니다."
L["Allow outside CineMode"] = "CineMode 밖에서도 허용"
L["CineMode hides your buffs and debuffs: pick what brings them back."] = "CineMode는 강화 및 약화 효과를 숨깁니다: 무엇으로 다시 보이게 할지 고르세요."
L["Gaining or refreshing a buff briefly shows your buffs and debuffs."] = "강화 효과를 얻거나 갱신하면 강화 및 약화 효과를 잠깐 보여 줍니다."
L["Lets this page bring your hidden buffs and debuffs back in CineMode."] = "이 페이지가 CineMode에서 숨긴 강화 및 약화 효과를 다시 보여 주게 합니다."
L["What brings your hidden buffs and debuffs up for a while."] = "숨긴 강화 및 약화 효과를 잠시 보여 주는 것."
L["Buffs you or your pet cast on yourself don't bring them up."] = "나나 소환수가 나에게 건 강화 효과로는 나타나지 않습니다."
L["Not while skyriding"] = "용 조련술 중에는 안 함"
L["No buff brings them up while you're on a skyriding mount."] = "용 조련술 탈것을 타고 있는 동안에는 어떤 강화 효과로도 나타나지 않습니다."
L["Only the buff you gained or refreshed shows."] = "얻거나 갱신한 강화 효과만 표시됩니다."
L["Keep ones lasting less than up until they run out"] = "이보다 짧은 효과는 끝날 때까지 유지"
L["A short buff stays up for as long as it lasts."] = "짧은 강화 효과는 지속되는 동안 계속 보입니다."
L["Gaining or refreshing a debuff briefly shows your debuffs."] = "약화 효과를 얻거나 갱신하면 약화 효과를 잠깐 보여 줍니다."
L["Only within the Calm Timer after a fight."] = "전투 후 진정 타이머 안에서만."
L["Keeps them up while you have any debuff."] = "약화 효과가 하나라도 있으면 계속 보입니다."
L["Debuffs that last longer than this don't bring them up."] = "이보다 오래 지속되는 약화 효과로는 나타나지 않습니다."
L["Override Default Buff Reveal Time"] = "기본 강화 효과 표시 시간 재정의"
L["How long a new buff keeps the buffs up."] = "새 강화 효과가 강화 효과를 보여 주는 시간."
L["Override Default Debuff Reveal Time"] = "기본 약화 효과 표시 시간 재정의"
L["How long a new debuff keeps the buffs up."] = "새 약화 효과가 강화 효과를 보여 주는 시간."
L["Gaining this doesn't bring your buffs up; type a spell ID or name."] = "이것을 얻어도 강화 효과가 나타나지 않습니다. 주문 ID나 이름을 입력하세요."
L["Keeps drifting to new random distances after the first pull-back."] = "처음 멀어진 뒤에도 계속 새 무작위 거리로 흘러갑니다."
L["How much closer than your own zoom the random zoom may come."] = "무작위 확대가 내 확대 거리보다 얼마나 더 가까이 올 수 있는지."
L["How much of each zoom is spent speeding up and slowing down."] = "각 확대/축소에서 가속과 감속에 쓰는 비율."
L["Each pause varies at random by up to this much."] = "각 멈춤이 최대 이만큼 무작위로 달라집니다."
L["Raises the game's max camera distance while pulled back."] = "멀어져 있는 동안 게임의 최대 카메라 거리를 늘립니다."
L["Lets the cameras start as the rows below say."] = "아래 줄 설정대로 카메라가 시작되게 합니다."
L["Top speed in the middle of a sweep."] = "한 바퀴 도는 중간의 최고 속도."
L["Each new angle is at least this many degrees from the last."] = "새 각도는 이전 각도와 최소 이만큼 차이 납니다."
L["How far the camera may sway to either side."] = "카메라가 양옆으로 흔들릴 수 있는 정도."
L["Each move also tilts the camera to a random angle between these limits."] = "동작마다 카메라를 이 범위 안의 무작위 각도로 기울이기도 합니다."
L["The camera never tilts more than this far below where it started."] = "카메라는 시작 지점보다 이 이상 아래로 기울지 않습니다."
L["How much of each move is spent speeding up and slowing down."] = "각 동작에서 가속과 감속에 쓰는 비율."
L["How long the camera rests between sweeps."] = "한 바퀴와 다음 바퀴 사이에 카메라가 쉬는 시간."
L["Puts this camera's settings back to your profile's values."] = "이 카메라의 설정을 프로필 값으로 되돌립니다."
L["Runs this camera for 30 seconds where you stand."] = "지금 서 있는 곳에서 이 카메라를 30초 동안 실행합니다."
L["The camera slowly pulls back, then drifts in and out."] = "카메라가 천천히 멀어진 뒤, 가까워졌다 멀어졌다 합니다."
L["After you move the camera yourself, it waits this long before carrying on."] = "카메라를 직접 움직이면 이만큼 기다렸다가 계속합니다."
L["Doing the emote or pressing the sit key."] = "감정 표현을 하거나 앉기 키를 누를 때."
L["Clicking Sit, Kneel or Lie down on the campfire card, or its fire button (Emote Vision)."] = "모닥불 카드의 앉기, 무릎 꿇기, 눕기나 불 버튼을 클릭할 때 (Emote Vision)."
L["Doing the emote, until you move or jump."] = "감정 표현을 할 때, 움직이거나 점프할 때까지."
L["Right-clicking a seat to sit on it."] = "의자를 오른쪽 클릭해서 앉을 때."
L["Unsheathing your weapon with your Sheathe key out of combat."] = "전투 밖에서 무기 넣기 키로 무기를 꺼낼 때."
L["Casting your Hearthstone."] = "귀환석을 시전할 때."
L["Casting a teleport spell."] = "순간이동 주문을 시전할 때."
L["Logging out where the game counts down first."] = "게임이 먼저 카운트다운하는 곳에서 로그아웃할 때."
L["Doing the emote while standing still."] = "가만히 서서 감정 표현을 할 때."
L["Casting Fishing, until you move or jump."] = "낚시를 시전할 때, 움직이거나 점프할 때까지."
L["Being flagged AFK."] = "자리 비움 상태일 때."
L["Standing still for the time below with nothing else going on."] = "다른 일 없이 아래 시간만큼 가만히 서 있을 때."
L["Taking off on a flight path."] = "비행 경로로 이륙할 때."
L["Talking to a quest giver."] = "퀘스트 NPC와 대화할 때."
L["Talking to an NPC about a quest step."] = "퀘스트 단계 때문에 NPC와 대화할 때."
L["On flight paths, the camera sways side to side with an occasional fly-by."] = "비행 경로에서 카메라가 좌우로 흔들리며 가끔 플라이바이를 합니다."
L["Your target's frames fade until you pick a new target or land."] = "새 대상을 잡거나 착륙할 때까지 대상 프레임이 흐려집니다."
L["Sway from side to side"] = "좌우로 흔들기"
L["The camera sways from side to side around where it started."] = "카메라가 시작한 곳을 중심으로 좌우로 흔들립니다."
L["Your character does /look as a fly-by starts, which players nearby see."] = "플라이바이가 시작될 때 캐릭터가 /look을 합니다. 근처 플레이어에게도 보입니다."
L["About one fly-by per this many seconds of flight."] = "비행 중 이 초마다 약 한 번 플라이바이."
L["Turn round"] = "돌아보기"
L["Turn back before landing"] = "착륙 전 되돌아가기"
L["Before you land, the camera turns back to where it was at takeoff."] = "착륙하기 전에 카메라가 이륙할 때의 방향으로 돌아갑니다."
L["Turned back by"] = "되돌아가기 완료 시점"
L["How long before landing the camera has settled."] = "착륙 얼마 전에 카메라가 자리 잡을지."
L["When you stand still a while or go AFK, the camera slowly circles your character."] = "한동안 가만히 서 있거나 자리를 비우면 카메라가 캐릭터 주위를 천천히 돕니다."
L["The camera sweeps around your character, pausing between sweeps."] = "카메라가 캐릭터 주위를 돌며, 한 바퀴마다 잠시 멈춥니다."
L["While you auto-run, the camera follows along until you stop or steer."] = "자동 달리기 중에는 멈추거나 방향을 틀 때까지 카메라가 따라갑니다."
L["The camera eases out a little, then drifts in and out."] = "카메라가 조금 멀어진 뒤, 가까워졌다 멀어졌다 합니다."
L["When you rest, sit or dance, the camera slowly turns to face you and eases in."] = "휴식하거나 앉거나 춤추면 카메라가 천천히 돌아 캐릭터를 마주 보고 다가옵니다."
L["How far the camera comes down toward the ground as it turns."] = "돌면서 카메라가 땅 쪽으로 내려오는 정도."
L["The camera eases in close, then drifts a little in and out."] = "카메라가 가까이 다가온 뒤, 조금씩 가까워졌다 멀어졌다 합니다."
L["The close-up distance the cozy camera zooms in to."] = "아늑한 카메라가 확대해 들어가는 근접 거리."
L["How much lower the camera sways, to look out across the view."] = "풍경을 내다보도록 카메라가 얼마나 낮게 흔들릴지."
L["The camera eases out a little, then drifts slowly in and out."] = "카메라가 조금 멀어진 뒤, 천천히 가까워졌다 멀어졌다 합니다."
L["The camera sways a little from side to side."] = "카메라가 좌우로 조금 흔들립니다."
L["How much lower the camera sways, to look out across the water."] = "물을 내다보도록 카메라가 얼마나 낮게 흔들릴지."
L["When you die, the camera slowly circles your body until you release or are revived."] = "죽으면 영혼을 놓거나 부활할 때까지 카메라가 시체 주위를 천천히 돕니다."
L["If you die in a boss fight, the death camera waits for it to end."] = "우두머리 전투에서 죽으면 죽음 카메라는 전투가 끝날 때까지 기다립니다."
L["No death camera when you can come back yourself, like with a soulstone."] = "영혼석처럼 스스로 되살아날 수 있을 때는 죽음 카메라가 없습니다."
L["Adds a button under the release popup to get your own view back."] = "영혼 해방 창 아래에 원래 시점으로 돌아가는 버튼을 추가합니다."
L["How far the camera pulls back while you're dead."] = "죽어 있는 동안 카메라가 멀어지는 거리."
L["How far the camera rises to look down on your body."] = "시체를 내려다보도록 카메라가 올라가는 높이."
L["The groups ticked here stay up while the death camera hides your frames."] = "죽음 카메라가 창을 숨기는 동안 여기 체크한 그룹은 계속 보입니다."
L["Music file IDs, separated by commas; one plays at random when you die."] = "음악 파일 ID, 쉼표로 구분. 죽으면 하나가 무작위로 재생됩니다."
L["The camera turns toward NPCs as they talk near you."] = "근처에서 NPC가 말하면 카메라가 그쪽으로 돕니다."
L["The fastest the camera swings toward a new speaker."] = "새로 말하는 사람 쪽으로 카메라가 도는 최대 속도."
L["How far from the screen's center the speaker ends up."] = "말하는 사람이 화면 가운데에서 얼마나 떨어진 곳에 놓일지."
L["How far the camera drifts side to side once settled."] = "자리 잡은 뒤 카메라가 좌우로 흘러가는 정도."
L["The camera turns around to find speakers you can't see."] = "보이지 않는 곳에서 말하는 사람을 찾으려고 카메라가 돌아봅니다."
L["Snaps to speakers, adds a tall letterbox with subtitles and fades the whole UI."] = "말하는 사람에게 바로 맞추고, 자막과 함께 높은 레터박스를 넣고, UI 전체를 흐리게 합니다."
L["How fast the camera zooms back out once the talking is over."] = "대화가 끝난 뒤 카메라가 다시 멀어지는 속도."
L["The longest a zoom in or out can take."] = "확대나 축소에 걸릴 수 있는 최대 시간."
L["How long no one must talk before the camera turns back."] = "카메라가 되돌아가기 전에 아무도 말하지 않아야 하는 시간."
L["When you talk to a quest giver, the camera zooms in and looks past you at them."] = "퀘스트 NPC와 대화하면 카메라가 확대해 캐릭터 너머로 NPC를 봅니다."
L["Also zooms in for NPCs with nothing to say about quests."] = "퀘스트와 상관없는 NPC에게도 확대합니다."
L["The camera stays put when a quest giver only has dailies or weeklies."] = "퀘스트 NPC에게 일일이나 주간 퀘스트만 있으면 카메라는 그대로 있습니다."
L["How far the camera turns to one side to look past you."] = "캐릭터 너머를 보려고 카메라가 한쪽으로 도는 정도."
L["How long the turn to the side takes."] = "옆으로 도는 데 걸리는 시간."
L["How fast the camera zooms back out once you walk away."] = "걸어서 떠나면 카메라가 다시 멀어지는 속도."
L["How far the camera comes down toward eye level."] = "카메라가 눈높이 쪽으로 내려오는 정도."
L["When you cast your Hearthstone or a teleport, the camera spins around you as it zooms in."] = "귀환석이나 순간이동을 시전하면 카메라가 확대하며 캐릭터 주위를 돕니다."
L["The distance the zoom ends at as the cast finishes."] = "시전이 끝날 때 확대가 멈추는 거리."
L["Canceling"] = "취소할 때"
L["If you cancel the cast, the camera turns back to where it was."] = "시전을 취소하면 카메라가 원래 자리로 돌아갑니다."
L["Extra settings for cameras that aren't on the Scripts page yet."] = "아직 스크립트 페이지에 없는 카메라의 추가 설정."
L["Mouse Turn"] = "마우스 회전"
L["Keeps right-mouse turning smooth by capping and easing its speed."] = "속도를 제한하고 완만하게 해서 오른쪽 마우스 회전을 부드럽게 합니다."
L["Cap"] = "제한"
L["Cap right-click turn speed"] = "오른쪽 클릭 회전 속도 제한"
L["Right-click turning never goes faster than the speed below."] = "오른쪽 클릭 회전이 아래 속도보다 빨라지지 않습니다."
L["Top turn speed"] = "최대 회전 속도"
L["The fastest you can turn."] = "돌 수 있는 최대 속도."
L["Ease back over"] = "복귀 시간"
L["How long your own Mouse Look Speed takes to come back after you slow down."] = "느려진 뒤 원래 마우스 시점 속도로 돌아오는 데 걸리는 시간."
L["Ramp up right-click turn speed"] = "오른쪽 클릭 회전 속도 점점 올리기"
L["Each right-click turn starts slow and builds up to your own speed."] = "오른쪽 클릭 회전이 느리게 시작해 원래 속도까지 올라갑니다."
L["Start at"] = "시작 속도"
L["%d%% of your speed"] = "원래 속도의 %d%%"
L["How fast a turn starts, as a share of your own Mouse Look Speed."] = "회전 시작 속도. 원래 마우스 시점 속도에 대한 비율."
L["Up to full speed over"] = "최대 속도까지 걸리는 시간"
L["How long a turn takes to build up to full speed."] = "회전이 최대 속도에 이르는 데 걸리는 시간."
L["Slow looking up and down too"] = "위아래 보기도 느리게"
L["Looking up and down slows by the same share as turning."] = "위아래 보기도 회전과 같은 비율로 느려집니다."
L["Turns the whole Atmosphere hub on or off at once."] = "분위기 연출 허브 전체를 한 번에 켜거나 끕니다."
L["How the game world looks in CineMode: vignette, inn glow, weather and depth of field."] = "CineMode에서 게임 월드의 모습: 비네트, 여관 불빛, 날씨, 피사계 심도."
L["Pick where and when each effect shows in CineMode."] = "CineMode에서 각 효과가 언제 어디서 보일지 고르세요."
L["Shows all the time in CineMode, fights included."] = "CineMode에서는 전투를 포함해 항상 보입니다."
L["Rain, snow and sandstorms tint the scene, more strongly in heavier weather."] = "비, 눈, 모래폭풍이 화면에 색을 입히며, 날씨가 거셀수록 더 강해집니다."
L["Reduce view distance in bad weather"] = "궂은 날씨에 시야 거리 줄이기"
L["Brings the view distance in during rain, snow or sandstorms, more the heavier it gets."] = "비, 눈, 모래폭풍 동안 시야 거리를 줄이며, 거셀수록 더 줄입니다."
L["The game's graphics settings one by one, shared by every profile on this computer."] = "게임 그래픽 설정을 하나하나. 이 컴퓨터의 모든 프로필이 함께 씁니다."
L["Uses the settings below, or the game's own when turned off."] = "아래 설정을 씁니다. 끄면 게임 기본 설정을 씁니다."
L["World"] = "월드"
L["Ground clutter, view distance, detail and shadows."] = "지면 표현, 시야 거리, 세부 묘사, 그림자."
L["Sky and water"] = "하늘과 물"
L["Clouds, fog, reflections and ripples."] = "구름, 안개, 반사, 물결."
L["Effects"] = "효과"
L["Particles, glow, blood and sharpening."] = "입자, 광원 효과, 피, 선명화."
L["HDR"] = "HDR"
L["HDR output and brightness."] = "HDR 출력과 밝기."
L["Nameplate distance and zoom distance."] = "이름표 거리와 확대/축소 거리."
L["How far away grass and flowers start thinning out."] = "풀과 꽃이 줄어들기 시작하는 거리."
L["How far the land is drawn in full; very demanding on frame rate."] = "지형을 온전히 그리는 거리. 프레임에 부담이 매우 큽니다."
L["How far away trees, rocks and other objects keep their full detail."] = "나무, 바위 등 사물이 세부 묘사를 유지하는 거리."
L["How far away small objects stay before they fade out."] = "작은 사물이 사라지기 전까지 보이는 거리."
L["How far away creatures and characters keep their full detail."] = "생물과 캐릭터가 세부 묘사를 유지하는 거리."
L["How far away nameplates show, in yards."] = "이름표가 보이는 거리 (미터)."
L["How far out you can zoom the camera."] = "카메라를 멀리 뺄 수 있는 거리."
L["Higher gives sharper shadow edges, lower saves frame rate."] = "높을수록 그림자 경계가 선명하고, 낮을수록 프레임을 아낍니다."
L["Horizon distance"] = "지평선 거리"
L["How far the flat horizon past the land reaches."] = "지형 너머 평평한 지평선이 닿는 거리."
L["Sky detail"] = "하늘 세부 묘사"
L["How detailed the clouds and sky are."] = "구름과 하늘의 세부 묘사 정도."
L["Volumetric fog"] = "입체 안개"
L["Fog with depth in place of the usual distance fog."] = "일반 거리 안개 대신 깊이감 있는 안개."
L["Water reflections"] = "물 반사"
L["How much of the world water reflects."] = "물이 월드를 얼마나 반사할지."
L["Water ripples"] = "물결"
L["How detailed the ripples on water are."] = "물결의 세부 묘사 정도."
L["Particle density"] = "입자 밀도"
L["How many particles spells and effects show."] = "주문과 효과가 보여 주는 입자의 양."
L["Full-screen glow"] = "전체 화면 광원 효과"
L["A soft glow around bright light."] = "밝은 빛 주위의 부드러운 광채."
L["Gray screen on death"] = "죽으면 회색 화면"
L["The world turns gray while you're dead."] = "죽어 있는 동안 세상이 회색으로 바뀝니다."
L["Blood and gore"] = "피 표현"
L["How much blood shows in fights, from none to the most."] = "전투에서 피가 보이는 정도, 없음부터 최대까지."
L["Always sharpen"] = "항상 선명하게"
L["Sharpens the picture even at full render scale."] = "렌더링 배율이 최대여도 화면을 선명하게 합니다."
L["HDR output"] = "HDR 출력"
L["Sends HDR to your monitor; Windows HDR must be on and Auto HDR off."] = "모니터에 HDR을 보냅니다. Windows HDR은 켜고 자동 HDR은 꺼야 합니다."
L["Use peak brightness"] = "최대 밝기 사용"
L["Peak brightness"] = "최대 밝기"
L["Your monitor's peak brightness, in nits."] = "모니터의 최대 밝기 (니트)."
L["HDR strength"] = "HDR 강도"
L["How strong HDR is; works with peak brightness only."] = "HDR의 강도. 최대 밝기와 함께일 때만 작동합니다."
L["Use reference brightness"] = "기준 밝기 사용"
L["Reference brightness"] = "기준 밝기"
L["How bright white looks in HDR, in nits."] = "HDR에서 흰색의 밝기 (니트)."
L["Sky and weather"] = "하늘과 날씨"
L["Water"] = "물"
L["Restart graphics"] = "그래픽 다시 시작"
L["Restarts the game's graphics without leaving the game; the screen goes black for a moment."] = "게임을 나가지 않고 그래픽을 다시 시작합니다. 화면이 잠깐 검게 됩니다."
L["Sound and music during CineMode; your own sound settings come back afterward."] = "CineMode 중의 소리와 음악. 끝나면 원래 소리 설정으로 돌아옵니다."
L["Plays music when a camera starts in CineMode and fades it out when the UI returns."] = "CineMode에서 카메라가 시작되면 음악을 재생하고, UI가 돌아오면 서서히 끕니다."
L["Pick where and when music can play in CineMode."] = "CineMode에서 음악이 언제 어디서 재생될 수 있는지 고르세요."
L["After a camera starts music, no camera starts it again for this long."] = "카메라가 음악을 시작한 뒤 이 시간 동안은 어떤 카메라도 다시 시작하지 않습니다."
L["Fades music out once you leave the camera modes and move on."] = "카메라 모드를 떠나 움직이면 음악을 서서히 끕니다."
L["Each row is a scene that plays its camera when one of its triggers happens."] = "각 줄은 발동 조건 중 하나가 일어나면 카메라를 재생하는 장면입니다."
L["Lets the scenes below play their cameras when their triggers happen."] = "아래 장면들이 발동 조건이 일어날 때 카메라를 재생하게 합니다."
L["Auto-running in walk mode."] = "걷기 모드로 자동 달리기."
L["Auto-running."] = "자동 달리기."
L["Dying, until you release or are resurrected."] = "죽었을 때, 영혼을 놓거나 부활할 때까지."
L["An NPC talking to you or your party; the camera swings toward whoever's talking."] = "NPC가 나나 파티에게 말할 때. 카메라가 말하는 쪽으로 돕니다."
L["Other NPCs talking near you, once you've stood still a while."] = "한동안 가만히 서 있을 때 근처에서 다른 NPC가 말할 때."
L["Starts music as this camera starts; needs the Audio page on."] = "이 카메라가 시작될 때 음악을 시작합니다. 소리 페이지가 켜져 있어야 합니다."
L["Plays a song of its own while the death camera runs."] = "죽음 카메라가 도는 동안 자체 음악을 재생합니다."
L["Brings CineMode on while this camera runs, when Start in CineMode is off."] = "'CineMode로 시작'이 꺼져 있으면 이 카메라가 도는 동안 CineMode를 켭니다."
L["Buff names or spell IDs, separated by commas."] = "강화 효과 이름 또는 주문 ID, 쉼표로 구분."
L["Words in an object's name that mark it as a seat, separated by commas."] = "사물 이름에 들어 있으면 의자로 보는 단어, 쉼표로 구분."
L["How long you stand still before this row's camera starts."] = "이 줄의 카메라가 시작되기 전에 가만히 서 있어야 하는 시간."
L["How long the camera waits on a quest window before it starts."] = "퀘스트 창이 열린 뒤 카메라가 시작되기까지 기다리는 시간."
L["How long the camera waits on the window before it starts."] = "창이 열린 뒤 카메라가 시작되기까지 기다리는 시간."
L["How long you stand still before NPCs chatting nearby start this camera."] = "근처에서 대화하는 NPC가 이 카메라를 시작하기 전에 가만히 서 있어야 하는 시간."
L["How long you keep going before this row's camera starts."] = "이 줄의 카메라가 시작되기 전에 계속해야 하는 시간."
L["Whether this row's camera may start in or after a fight."] = "이 줄의 카메라가 전투 중이나 전투 후에 시작해도 되는지."
L["Where this row's camera may start."] = "이 줄의 카메라가 시작할 수 있는 곳."
L["Pause cameras while a window is open"] = "창이 열려 있으면 카메라 일시 정지"
L["Scenes pause while a window like the map or spellbook is open."] = "지도나 주문책 같은 창이 열려 있는 동안 장면이 멈춥니다."
L["Lists the rows by camera name or by scene name."] = "줄을 카메라 이름이나 장면 이름으로 나열합니다."
L["Make a scene of your own with its triggers, camera and end."] = "발동 조건, 카메라, 끝을 정한 나만의 장면을 만듭니다."
L["A scene of your own; open it to set its triggers and when it ends."] = "나만의 장면. 열어서 발동 조건과 끝나는 때를 정하세요."
L["Copies this row just below, so you can give it another camera."] = "이 줄을 바로 아래에 복사해 다른 카메라를 줄 수 있게 합니다."
L["Deletes this scene so it starts no camera."] = "이 장면을 삭제해 어떤 카메라도 시작하지 않게 합니다."
L["Your own name for this row, shown on the grid."] = "격자에 표시할 이 줄의 이름."
L["The camera this row starts."] = "이 줄이 시작하는 카메라."
L["This row's camera may start anywhere."] = "이 줄의 카메라는 어디서나 시작할 수 있습니다."
L["Indoors, the camera modes zoom out and swing less so they don't hit walls."] = "실내에서는 카메라 모드가 덜 멀어지고 덜 돌아서 벽에 부딪히지 않게 합니다."
L["How far past your own distance the slow zoom may pull back indoors."] = "실내에서 느린 축소가 내 거리보다 얼마나 더 멀어질 수 있는지."
L["Stops the AFK camera sweeping around you indoors, where it can hit walls."] = "벽에 부딪힐 수 있는 실내에서는 자리 비움 카메라가 캐릭터 주위를 돌지 않게 합니다."
L["Shows it whenever its frame shows, hovered or not."] = "마우스를 올렸든 아니든 그 창이 보일 때마다 표시합니다."
L["Shows it the whole time, CineMode or not."] = "CineMode 여부와 상관없이 내내 표시합니다."
L["CineMode hides everything: pick which frames show, and when."] = "CineMode는 모든 것을 숨깁니다: 어떤 창을 언제 보일지 고르세요."
L["CineMode hides everything: tick which frames show, and when."] = "CineMode는 모든 것을 숨깁니다: 어떤 창을 언제 보일지 체크하세요."
L["CineMode hides these frames, and shows them only when their rows say."] = "CineMode는 이 창들을 숨기고, 줄 설정에 맞을 때만 보여 줍니다."
L["CineMode hides the frames in this section, and shows them only when their rows say."] = "CineMode는 이 섹션의 창을 숨기고, 줄 설정에 맞을 때만 보여 줍니다."
L["Not in use"] = "사용 안 함"
L["Shows or hides its parts."] = "구성 요소를 표시하거나 숨깁니다."
L["Shows the same parts as the Target rows."] = "대상 줄과 같은 구성 요소를 표시합니다."
L["Raid-style party frames follow the Raid tab's rows."] = "공격대 스타일 파티 창은 공격대 탭의 줄을 따릅니다."
L["Same as"] = "같게:"
L["raid frames"] = "공격대 창"
L["Opens the Raid tab."] = "공격대 탭을 엽니다."
L["Your Edit Mode layout has Use Raid-Style Party Frames ticked."] = "편집 모드 배치에서 '공격대 스타일 파티 창 사용'이 체크되어 있습니다."
L["Your Edit Mode layout has Use Raid-Style Party Frames unticked."] = "편집 모드 배치에서 '공격대 스타일 파티 창 사용'이 해제되어 있습니다."
L["Hide keybinds"] = "단축키 숨기기"
L["Hides the key names on the action bar buttons (1, a-Q, s-2...), CineMode or not."] = "CineMode 여부와 상관없이 행동 단축바 버튼의 키 이름(1, a-Q, s-2...)을 숨깁니다."
L["Hide macro names"] = "매크로 이름 숨기기"
L["Hides the macro names on the action bar buttons, CineMode or not."] = "CineMode 여부와 상관없이 행동 단축바 버튼의 매크로 이름을 숨깁니다."
L["Show while the spellbook is open"] = "주문책이 열려 있을 때 표시"
L["Keeps your action bars up while the spellbook or macros window is open."] = "주문책이나 매크로 창이 열려 있는 동안 행동 단축바를 계속 보여 줍니다."
L["PRD"] = "개인 자원"
L["Timers"] = "타이머"
L["Highlight"] = "강조"
L["CineMode hides the unit frames: pick which show, and when."] = "CineMode는 유닛 프레임을 숨깁니다: 어떤 것을 언제 보일지 고르세요."
L["CineMode hides your personal resource display: pick which parts show, and when."] = "CineMode는 개인 자원 표시를 숨깁니다: 어떤 부분을 언제 보일지 고르세요."
L["CineMode hides your cast bar: pick when it shows."] = "CineMode는 시전 바를 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides the action bars: pick which show, and when."] = "CineMode는 행동 단축바를 숨깁니다: 어떤 것을 언제 보일지 고르세요."
L["CineMode hides your buffs and debuffs: pick when they show."] = "CineMode는 강화 및 약화 효과를 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides timers and meters: pick which show, and when."] = "CineMode는 타이머와 측정기를 숨깁니다: 어떤 것을 언제 보일지 고르세요."
L["CineMode hides the Cooldown Manager: pick which bars show, and when."] = "CineMode는 재사용 대기시간 관리자를 숨깁니다: 어떤 바를 언제 보일지 고르세요."
L["CineMode hides your swing timer: pick when it shows."] = "CineMode는 평타 타이머를 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides the chat window: pick when it shows."] = "CineMode는 대화창을 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides info frames and menus: pick which show, and when."] = "CineMode는 정보 창과 메뉴를 숨깁니다: 어떤 것을 언제 보일지 고르세요."
L["CineMode hides the minimap: pick which parts show, and when."] = "CineMode는 미니맵을 숨깁니다: 어떤 부분을 언제 보일지 고르세요."
L["CineMode hides the quest tracker: pick when it shows."] = "CineMode는 퀘스트 추적기를 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides the party frames: pick when they show."] = "CineMode는 파티 창을 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides the raid frames: pick when they show."] = "CineMode는 공격대 창을 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides the raid-style party frames: pick when they show."] = "CineMode는 공격대 스타일 파티 창을 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides your character's highlight: pick when it shows."] = "CineMode는 캐릭터 강조를 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides these frames: pick which show, and when."] = "CineMode는 이 창들을 숨깁니다: 어떤 것을 언제 보일지 고르세요."
L["Pick where chat bubbles show."] = "말풍선이 어디서 보일지 고르세요."
L["Pick where and when each kind of bubble shows."] = "각 종류의 말풍선이 언제 어디서 보일지 고르세요."
L["These bubbles show everywhere, in fights and out."] = "이 말풍선은 전투 중이든 아니든 어디서나 보입니다."
L["Cinematic draws its own bubbles for speech whose game bubble you can't see."] = "게임 말풍선이 보이지 않는 말에는 Cinematic이 자체 말풍선을 그립니다."
L["Shows speech from someone off screen in a bubble low on the screen."] = "화면 밖에 있는 사람의 말을 화면 아래쪽 말풍선에 표시합니다."
L["Opens the Chat Bubble Style page: how off-screen bubbles look and where they show."] = "말풍선 스타일 페이지를 엽니다: 화면 밖 말풍선의 모양과 위치."
L["Shows emotes in the off-screen bubbles too, instead of in chat."] = "감정 표현도 대화창 대신 화면 밖 말풍선에 표시합니다."
L["Moves bubbles at the very top of the screen down where you can read them."] = "화면 맨 위의 말풍선을 읽을 수 있는 곳으로 내립니다."
L["Small helpers for getting around the world."] = "월드를 돌아다니는 데 도움이 되는 작은 기능."
L["Turns all the Quality of Life helpers on or off."] = "모든 편의 기능을 켜거나 끕니다."
L["Opens the character window when you drag gear out of your bags."] = "가방에서 장비를 끌어내면 캐릭터 창을 엽니다."
L["Adds a button to view the talents of someone you inspect."] = "살펴보기한 사람의 특성을 보는 버튼을 추가합니다."
L["Adds a talent calculator button to your talents window to plan a build."] = "특성 창에 빌드를 계획하는 특성 계산기 버튼을 추가합니다."
L["Moves game windows away from the left edge so your character stays in view."] = "게임 창을 왼쪽 가장자리에서 떨어뜨려 캐릭터가 계속 보이게 합니다."
L["Lets you drag the game's windows to move them."] = "게임 창을 끌어서 옮길 수 있게 합니다."
L["Adds an icon to chat windows to copy their text."] = "대화창에 글을 복사하는 아이콘을 추가합니다."
L["Keep chat history"] = "대화 기록 유지"
L["Chat windows bring back their last lines after a reload or login."] = "다시 불러오거나 접속한 뒤 대화창에 마지막 줄들을 되살립니다."
L["Show the time on those lines"] = "그 줄에 시각 표시"
L["Puts the time at the start of brought-back lines."] = "되살린 줄 앞에 시각을 붙입니다."
L["Show XP left to level"] = "레벨업까지 남은 경험치 표시"
L["Shows how much XP you still need for the next level."] = "다음 레벨까지 필요한 경험치를 보여 줍니다."
L["The camera zooms to the distance below when you log in or reload."] = "접속하거나 다시 불러오면 카메라가 아래 거리로 확대/축소합니다."
L["The camera distance to start at."] = "시작할 카메라 거리."
L["A button at the top of the screen that reloads the UI in one click."] = "한 번 클릭으로 UI를 다시 불러오는 화면 위쪽 버튼."
L["Reopens the windows you had open after a reload."] = "다시 불러온 뒤 열려 있던 창을 다시 엽니다."
L["Hides floating damage and healing numbers in CineMode out of combat."] = "전투 밖 CineMode에서 떠오르는 피해량 및 치유량 숫자를 숨깁니다."
L["Hides the red error text while you're fighting."] = "전투 중에 빨간 오류 문구를 숨깁니다."
L["Hides the red error text while you're out of combat."] = "전투 밖에서 빨간 오류 문구를 숨깁니다."
L["Turns the Hunter helpers on or off."] = "사냥꾼 편의 기능을 켜거나 끕니다."
L["Right-clicking an enemy uses Auto Shot when it's far enough away."] = "충분히 멀리 있는 적을 오른쪽 클릭하면 자동 사격을 씁니다."
L["Moves the smallest ammo stack first after Clean Up Bags, so it's shot first."] = "가방 정리 후 가장 적은 탄약 묶음을 맨 앞으로 옮겨 먼저 쏘게 합니다."
L["Adds a Fill button at vendors that fills your quiver with ammo."] = "상인 창에 화살통을 탄약으로 채우는 채우기 버튼을 추가합니다."
L["Keeps your pet frame up while your pet isn't happy."] = "소환수가 만족스럽지 않은 동안 소환수 프레임을 계속 보여 줍니다."
L["The pet frame fades with the UI while a camera mode runs."] = "카메라 모드가 도는 동안 소환수 프레임이 UI와 함께 흐려집니다."
L["Move Questie's nameplate icons"] = "Questie의 이름표 아이콘 옮기기"
L["Moves Questie's quest icons beside the name, where Cinematic's quest mark goes."] = "Questie의 퀘스트 아이콘을 Cinematic 퀘스트 표시 자리인 이름 옆으로 옮깁니다."
L["Move EnhanceQoL's nameplate quest marks"] = "EnhanceQoL의 이름표 퀘스트 표시 옮기기"
L["Keeps EnhanceQoL's quest marks up, beside the name where Cinematic's would go."] = "EnhanceQoL의 퀘스트 표시를 Cinematic 표시 자리인 이름 옆에 계속 보여 줍니다."
L["Addon Support"] = "애드온 지원"
L["Settings for how Cinematic works with your other addons."] = "Cinematic이 다른 애드온과 함께 작동하는 방식에 대한 설정."
L["Turns Cinematic's support for your other addons on or off."] = "다른 애드온에 대한 Cinematic의 지원을 켜거나 끕니다."
L["Right-click casts Fishing again and the Fishing cast bar hides, as this page says."] = "이 페이지 설정대로 오른쪽 클릭으로 다시 낚시를 시전하고 낚시 시전 바를 숨깁니다."
L["Hides your cast bar while you're fishing."] = "낚시하는 동안 시전 바를 숨깁니다."
L["Right-click"] = "오른쪽 클릭"
L["Interact key"] = "상호작용 키"
L["Jump key"] = "점프 키"
L["Middle mouse button"] = "마우스 가운데 버튼"
L["Mouse button 4"] = "마우스 4번 버튼"
L["Mouse button 5"] = "마우스 5번 버튼"
L["With a fishing pole equipped, these cast Fishing when nothing is near."] = "낚싯대를 장착하고 주변에 아무것도 없으면 이것들로 낚시를 시전합니다."
L["Cast with"] = "시전 방법"
L["How long after a cast ends before right-click casts again."] = "시전이 끝난 뒤 오른쪽 클릭으로 다시 시전할 수 있기까지의 시간."
L["After a failed cast, right-click goes back to normal for this long."] = "시전에 실패하면 이 시간 동안 오른쪽 클릭이 평소대로 돌아갑니다."
L["Reel in with same key/click"] = "같은 키/클릭으로 낚아채기"
L["Reels in with the same click or key you cast with."] = "시전한 것과 같은 클릭이나 키로 낚아챕니다."
L["In gamepad mode, the button below casts Fishing like right-click does."] = "게임패드 모드에서는 아래 버튼이 오른쪽 클릭처럼 낚시를 시전합니다."
L["Sound"] = "소리"
L["Louder while fishing"] = "낚시 중 소리 키우기"
L["Turns the game's volume up while your bobber is out, so you hear a bite."] = "낚시찌가 나가 있는 동안 게임 음량을 키워 입질 소리를 들을 수 있게 합니다."
L["Master volume"] = "주 음량"
