L["Sound effects volume"] = "효과음 음량"
L["Sound in the background too"] = "백그라운드에서도 소리"
L["Keeps the game's sound playing in the background while you fish."] = "낚시하는 동안 게임이 백그라운드에 있어도 소리를 계속 재생합니다."
L["CineMode hides the gamepad's bars, button hints and reticle: pick when they show."] = "CineMode는 게임패드 바, 버튼 안내, 조준점을 숨깁니다: 언제 보일지 고르세요."
L["CineMode hides the gamepad's frames, and shows them only when their rows say."] = "CineMode는 게임패드 창을 숨기고, 줄 설정에 맞을 때만 보여 줍니다."
L["Which gamepad frames show in CineMode, and when."] = "CineMode에서 어떤 게임패드 창을 언제 보일지."
L["What brings the gamepad action bars up, and how they fade."] = "게임패드 행동 단축바를 불러오는 것과 흐려지는 방식."
L["Gamepad frames"] = "게임패드 창"
L["Keeps the gamepad's interact prompt up in CineMode as nameplates fade."] = "CineMode에서 이름표가 흐려져도 게임패드 상호작용 안내는 계속 보여 줍니다."
