L["Heal Vision out of fights while you have anything else targeted."] = "전투 밖에서 다른 것을 대상으로 잡고 있는 동안의 Heal Vision."
L["Heal Vision everywhere."] = "어디서나 Heal Vision."
L["Heal Vision's settings while you're a tank."] = "방어 전담일 때의 Heal Vision 설정."
L["Heal Vision's settings while you're a healer."] = "치유 전담일 때의 Heal Vision 설정."
L["Heal Vision's settings while you're dealing damage."] = "공격 전담일 때의 Heal Vision 설정."
L["Heal Vision on your party and raid frames."] = "파티 및 공격대 창의 Heal Vision."
L["Heal Vision on friendly nameplates."] = "아군 이름표의 Heal Vision."
L["Uses the Default tab's settings for this role."] = "이 역할에 기본 탭의 설정을 씁니다."
