L["Your target always shows at least this much."] = "내 대상은 항상 최소 이만큼 보입니다."
L["The member under your mouse shows at least this much; 0% turns it off."] = "마우스 아래의 구성원은 최소 이만큼 보입니다. 0%면 끕니다."
