L["Other players"] = "다른 플레이어"
L["Another player's plate shows once their health drops below this."] = "다른 플레이어의 이름표는 생명력이 이 아래로 떨어지면 나타납니다."
L["How much of a hidden player's plate still shows."] = "숨겨진 플레이어 이름표가 여전히 보이는 정도."
L["A pet's or minion's plate shows once its health drops below this."] = "소환수나 하수인의 이름표는 생명력이 이 아래로 떨어지면 나타납니다."
L["How much of a hidden pet's plate still shows."] = "숨겨진 소환수 이름표가 여전히 보이는 정도."
L["Hold your Show hidden tooltips key to see a hidden tooltip in CineMode."] = "CineMode에서 숨긴 툴팁을 보려면 '숨긴 툴팁 보기' 키를 누르고 있으세요."
