L["How long tooltips take to fade in and out."] = "툴팁이 나타나고 사라지는 데 걸리는 시간."
L["Hides tooltips once the mouse is still, or shows them only once it's still."] = "마우스가 멈추면 툴팁을 숨기거나, 멈췄을 때만 보여 줍니다."
