-- Changelog.lua
L["A button on the main page puts Cinematic back to a fresh install."] = "메인 페이지의 버튼으로 Cinematic을 새로 설치한 상태로 되돌립니다."
L["A fishing camera and settings of its own."] = "낚시 카메라와 전용 설정."
