L["Add any addon's frame by clicking it, and Bartender4's bars fade too."] = "아무 애드온의 창이나 클릭해서 추가하고, Bartender4의 바도 흐려집니다."
L["Add mode and Bartender4"] = "추가 모드와 Bartender4"
