L["Battle Vision"] = "Battle Vision"
L["Boss cards"] = "우두머리 카드"
L["Both fade with the rest of the UI in CineMode."] = "CineMode에서 둘 다 나머지 UI와 함께 흐려집니다."
L["Built-in profiles to start from, picked in a welcome window, and as many of your own as you like."] = "환영 창에서 고르는 기본 제공 프로필, 그리고 원하는 만큼 만드는 나만의 프로필."
L["By a campfire a button lets you sit, kneel or lie down, with a cozy camera of its own."] = "모닥불 옆에서 버튼으로 앉거나 무릎 꿇거나 누울 수 있고, 전용 아늑한 카메라가 따라옵니다."
